compatibilityPatch.after:
// Atlas CI compatibility: ephemeral GitHub runner only; all Hallmark gates stay intact.
const atlasCiArgs = process.env.GITHUB_ACTIONS === 'true' && process.env.HALLMARK_CI_CHROME_ARGS === 'ephemeral-ci'
  ? ['--no-sandbox', '--disable-dev-shm-usage', '--disable-background-networking', '--no-first-run'] : [];
const browser = await puppeteer.launch({ executablePath: chrome, headless: true, args: atlasCiArgs });

readinessPatch.after:
if (nav.r && isUrl(file) && !nav.r.ok() && nav.r.status() !== 304) throw new Error(`HTTP ${nav.r.status()} from ${file}`);
if (process.env.HALLMARK_ATLAS_READY === '1') {
  if (!isUrl(file)) throw new Error('Atlas readiness requires an HTTP URL');
  const atlasUrl = new URL(file);
  const atlasPage = atlasUrl.searchParams.get('page');
  const atlasSymbol = (atlasUrl.searchParams.get('symbol') || 'BTCUSD').toUpperCase();
  const atlasRoute = atlasUrl.pathname.endsWith('/mobile-preview.html') ? 'mobile-preview'
    : atlasPage === 'data' ? 'data'
    : atlasPage === 'evidence' ? 'evidence'
    : atlasPage === 'compare' && atlasUrl.searchParams.get('legacy') === '1' ? 'compare'
    : !atlasPage ? ({ BTCUSD: 'btc', ETHUSD: 'eth', BMNR: 'bmnr', MSTR: 'mstr' })[atlasSymbol] : null;
  if (!atlasRoute) throw new Error('Unsupported Atlas readiness route: ' + file);
  await page.waitForFunction((name) => {
    const doc = name === 'mobile-preview' ? document.querySelector('#mobile-preview')?.contentDocument : document;
    if (!doc || doc.documentElement.dataset.boot !== 'ready') return false;
    if ((name === 'btc' || name === 'mobile-preview') && (doc.querySelector('.atlas-plot[aria-busy="true"]') || doc.querySelector('.workspace-toast:not([hidden])'))) return false;
    if (name === 'data') return doc.querySelectorAll('#data-body tr[data-asset-symbol]').length === 18;
    if (name === 'evidence') return doc.querySelectorAll('#evidence-body [data-evidence-detail]').length > 0;
    if (name === 'compare') return doc.querySelectorAll('#structure-chart path').length > 0 && doc.querySelectorAll('#structure-cycles tr').length > 0;
    if (name === 'eth') return Number(doc.querySelector('#eth-chart')?.dataset.observedCandleCount) > 0;
    if (name === 'bmnr' || name === 'mstr') return Number(doc.querySelector('#equity-chart')?.dataset.observedCandleCount) > 0;
    return doc.querySelectorAll('#lab-chart path').length > 0;
  }, { timeout: 30000 }, atlasRoute);
  console.error('HALLMARK_RENDER_READY ' + JSON.stringify({ url: file, route: atlasRoute }));
}
